/* HOME: original vector illustrations and local interactions. No vendor assets or services. */
window.HomeUI=(()=>{
  const state={tab:'dashboard',collapsed:new Set(),shortcuts:[],preview:null};
  const catalog=DeviceRegistry.all;
  const icon=name=>Icons.render(name);
  const illustration=id=>DeviceVisuals.render(id);
  function section(key,label,content){const closed=state.collapsed.has(key);return `<section class="home-section"><button class="home-section-heading" data-collapse="${key}" aria-expanded="${!closed}"><span class="disclosure ${closed?'collapsed':''}"></span>${label}</button><div ${closed?'hidden':''}>${content}</div></section>`;}
  const moduleData=[['profiles','LOCAL PROFILES','profiles'],['linked','LINKED APPLICATIONS','linked'],['macro','MACROS · NOT INTEGRATED','macro'],['tour','ABOUT SECBIRD','tour']];
  function dashboard(){return section('devices','DETECTED DEVICES',status()+`<div class="home-card-grid">${catalog.map(d=>UI.deviceCard(d,d.configurable?store[d.id].active:null)).join('')}</div>`)+section('modules','MODULES',`<div class="home-card-grid">${moduleData.map(([id,label,glyph])=>`<button class="home-module-card" data-home-module="${id}" ${id==='macro'?'disabled title="Macro editor is not integrated in this interface"':''}><span class="module-circle">${icon(glyph)}</span><span>${label}</span></button>`).join('')}</div>`)+`<div class="home-footnote">Live USB discovery · No settings sent · Independent of Razer</div>`;}
  function status(){if(HardwareSource.state==='loading')return '<div class="device-empty" role="status">Looking for connected Razer devices…</div>';if(HardwareSource.state==='error')return `<div class="device-empty" role="alert">${escapeHtml(HardwareSource.error)}<br><button id="scan-devices">Try again</button></div>`;if(!catalog.length)return '<div class="device-empty">No Razer HID devices detected on this PC.<br><small>Connect a device or its receiver, then refresh. No simulated devices will be added.</small></div>';return '<p class="detection-note">Interfaces present on this PC. Detection does not imply settings support; a wireless receiver does not confirm its device is connected over radio.</p>';}
  function modules(){return `<div class="modules-page"><h1>DEVICES</h1><div class="module-table">${catalog.filter(d=>!d.receiver).map(d=>`<div class="module-table-row"><span class="table-icon">${icon(d.art)}</span><span>${escapeHtml(d.name)}</span><span class="table-date">${escapeHtml(d.connection)}</span><button class="text-link" data-home-device="${d.id}">Configure</button></div>`).join('')}</div><h1>MODULES SECBIRD</h1><div class="module-status-grid"><section class="module-status-card"><h2>Local profiles</h2><p>Create, duplicate, import and export local profile drafts for all devices.</p><button data-page="profiles">Open profiles</button></section><section class="module-status-card"><h2>Linked applications</h2><p>Associations are saved locally. Automatic switching is not connected to the engine yet.</p><button data-page="profiles">Manage associations</button></section><section class="module-status-card"><h2>Onboard macros</h2><p>The Secbird engine includes macro functions. This interface does not yet include the editor or hardware integration.</p><button disabled>Not integrated</button></section><section class="module-status-card"><h2>Synapse services</h2><p>Alexa, Exchange, Gamer Room and proprietary Synapse migration are unavailable in this offline fork.</p><button disabled>Unavailable</button></section></div></div>`;}
  function room(){return `<div class="room-page"><section class="room-hero"><div class="room-placeholder-icon">${icon('lighting')}</div><div class="room-copy"><h1>GAMER ROOM</h1><p>THE FUTURE IS BRIGHT</p><p>A preview of your lighting space.<br>Not integrated · no hardware control.</p></div><span class="room-marker marker-one">○ <span>Ambient light</span></span><span class="room-marker marker-two">○ <span>Light strip</span></span><span class="room-marker marker-three"><span>Desk lamp</span> ○</span><button class="room-learn text-link" disabled title="Not integrated">Learn More ↗</button></section>${section('override','SYNAPSE OVERRIDE ⓘ','<div class="empty-device"><span>Devices with lighting override enabled will be displayed here.</span><button class="text-link" disabled title="Not integrated">Add a new device</button></div>')}${section('controlled','CONTROLLED BY GAMER ROOM APP ⓘ','<div class="empty-device">Devices controlled remotely from a room app will be displayed here.</div>')}<div class="home-footnote">Visual preview only · No Gamer Room or Chroma control</div></div>`;}
  function shortcuts(){return `<section class="shortcut-panel"><div class="shortcut-heading"><h1>SHORTCUTS</h1><button data-shortcut-add aria-label="Add shortcut">${icon('plus')}</button></div><p>Global shortcuts are custom key combinations that work across all device profiles. This preview stores them locally without capturing system input.</p>${state.shortcuts.map((s,i)=>`<div class="shortcut-row"><kbd>${escapeHtml(s.keys)}</kbd><span>${escapeHtml(s.action)}</span><button data-shortcut-remove="${i}" aria-label="Delete shortcut">×</button></div>`).join('')}<button class="add-shortcut" data-shortcut-add>ADD A SHORTCUT</button><form id="home-shortcut-form" hidden><label>KEY COMBINATION<input name="keys" placeholder="Ctrl + Shift + 1" maxlength="40" required></label><label>ACTION<select name="action"><option>Switch profile</option><option>Lighting on / off</option><option>Cycle DPI stage</option></select></label><div><button type="button" data-shortcut-cancel>Cancel</button><button class="home-install" type="submit">Add</button></div><small>Preview only; no system shortcut is registered.</small></form></section>`;}
  function escapeHtml(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  function render(){return `<div class="home-content home-${state.tab}">${({dashboard,modules,room,shortcuts}[state.tab])()}</div>`;}
  function refreshChrome(){document.querySelectorAll('[data-home-tab]').forEach(b=>{const selected=b.closest('.home-navigation')&&state.tab===b.dataset.homeTab&&document.body.classList.contains('home-view');b.classList.toggle('selected',!!selected);if(selected)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});}
  function showInfo(id){const messages={receiver:'HyperSpeed receiver: visual presentation only. No hardware pairing.',linked:'Application associations are saved locally. Engine integration is pending.',macro:'Macro editor is not integrated. No onboard writes.',tour:'HOME: Dashboard, Gamer Room, Devices & Modules and Global Shortcuts.',room:'Gamer Room is unavailable in this offline fork.'};notice(messages[id]||'Feature unavailable in this offline preview.');}
  document.addEventListener('click',event=>{
    const b=event.target.closest('button');if(!b)return;
    if(b.dataset.homeTab){state.tab=b.dataset.homeTab;navigate('dashboard');}

    if(b.dataset.collapse){state.collapsed.has(b.dataset.collapse)?state.collapsed.delete(b.dataset.collapse):state.collapsed.add(b.dataset.collapse);renderAppPreservingScroll();}
    if(b.dataset.homeDevice){if(!DeviceRegistry.get(b.dataset.homeDevice).configurable)showInfo('receiver');else navigate('device',b.dataset.homeDevice);}
    if(b.dataset.homeModule){if(['profiles','linked'].includes(b.dataset.homeModule))navigate('profiles');else showInfo(b.dataset.homeModule);}
    if(b.dataset.homeInfo)showInfo(b.dataset.homeInfo);
    if(b.hasAttribute('data-shortcut-add')){document.getElementById('home-shortcut-form').hidden=false;document.querySelector('#home-shortcut-form input').focus();}
    if(b.hasAttribute('data-shortcut-cancel'))document.getElementById('home-shortcut-form').hidden=true;
    if(b.dataset.shortcutRemove!==undefined){state.shortcuts.splice(Number(b.dataset.shortcutRemove),1);saveShortcuts();renderAppPreservingScroll();}

    if(b.dataset.window&&window.__TAURI__){const w=window.__TAURI__.window.getCurrentWindow();const action={minimize:()=>w.minimize(),maximize:()=>w.toggleMaximize(),close:()=>w.close()}[b.dataset.window];action?.().catch(e=>notice(String(e)));}
  });
  document.addEventListener('submit',event=>{if(event.target.id!=='home-shortcut-form')return;event.preventDefault();const data=new FormData(event.target);const keys=String(data.get('keys')).trim();if(!keys)return;state.shortcuts.push({keys,action:String(data.get('action'))});saveShortcuts();renderAppPreservingScroll();});
  function saveShortcuts(){try{localStorage.setItem('secbird-home-shortcuts',JSON.stringify(state.shortcuts));}catch{notice('Shortcuts kept for this session only.');}}
  try{const saved=JSON.parse(localStorage.getItem('secbird-home-shortcuts')||'[]');if(Array.isArray(saved))state.shortcuts=saved.filter(s=>typeof s.keys==='string'&&s.keys.length<=40&&typeof s.action==='string').slice(0,50);}catch{}
  function renderAppPreservingScroll(){const main=document.getElementById('main'),top=main.scrollTop;window.render();main.scrollTop=top;}
  document.addEventListener('DOMContentLoaded',()=>{if(window.__TAURI__)document.querySelectorAll('[data-window]').forEach(b=>b.disabled=false);});
  return {render,refreshChrome,catalog,icon,getTab:()=>state.tab,setTab:value=>{if(['dashboard','modules','room','shortcuts'].includes(value))state.tab=value;}};
})();
